    __m256d v_four = _mm256_set1_pd(4.0);

    __m256d cr0 = _mm256_set_pd(x0 + 3 * dx, x0 + 2 * dx, x0 + dx, x0);
    __m256d cr1 = _mm256_set_pd(x0 + 7 * dx, x0 + 6 * dx, x0 + 5 * dx, x0 + 4 * dx);

