        zr0 = _mm256_add_pd(_mm256_sub_pd(zr0_sq, zi0_sq), cr0);

        zi1 = _mm256_fmadd_pd(_mm256_add_pd(zr1, zr1), zi1, v_ci);
        zr1 = _mm256_add_pd(_mm256_sub_pd(zr1_sq, zi1_sq), cr1);
    }

    __m256d zr0_sq = _mm256_mul_pd(zr0, zr0);
    __m256d zi0_sq = _mm256_mul_pd(zi0, zi0);
    __m256d zr1_sq = _mm256_mul_pd(zr1, zr1);
