                zi = 2.0 * zr * zi + ci;
                zr = zr2 - zi2 + cr;
            }
            if (inside && (zr * zr + zi * zi <= 4.0)) {
                byte |= (1 << (7 - bit));
            }
        }
    }
    return byte;
}

