#include <algorithm>
#include <atomic>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <thread>
#include <vector>

struct Node {
    Node* left;
    Node* right;
};

inline Node* make_tree(int depth, Node*& ptr) {
    Node* node = ptr++;
    if (depth > 0) {
        node->left = make_tree(depth - 1, ptr);
        node->right = make_tree(depth - 1, ptr);
    } else {
        node->left = nullptr;
        node->right = nullptr;
    }
    return node;
}

inline int check_tree(const Node* node) {
    if (!node->left) return 1;
    return 1 + check_tree(node->left) + check_tree(node->right);
}

struct DepthInfo {
    int depth;
    int total_iters;
};

struct Task {
    int depth;
    int iters;
    int depth_idx;
};

int main(int argc, char* argv[]) {
    int n = 21;
    if (argc > 1) {
        n = std::atoi(argv[1]);
    }

    int stretch_depth = n + 1;

    // 1. Stretch tree
    {
        size_t stretch_nodes = 1ULL << (stretch_depth + 1);
        Node* stretch_buf = static_cast<Node*>(std::malloc(stretch_nodes * sizeof(Node)));
        Node* ptr = stretch_buf;
        Node* stretch_tree = make_tree(stretch_depth, ptr);
        int stretch_check = check_tree(stretch_tree);
        std::free(stretch_buf);
        std::printf("stretch tree of depth %d\t check: %d\n", stretch_depth, stretch_check);
    }

    // 2. Long-lived tree
    size_t long_lived_nodes = 1ULL << (n + 1);
    Node* long_lived_buf = static_cast<Node*>(std::malloc(long_lived_nodes * sizeof(Node)));
    Node* long_ptr = long_lived_buf;
    Node* long_lived_tree = make_tree(n, long_ptr);

    // 3. Prepare depth ranges and task queue for short-lived trees
    std::vector<DepthInfo> depths;
    int max_short_depth = 0;
    for (int d = 4; d <= n; d += 2) {
        depths.push_back({d, 1 << (n - d + 4)});
        max_short_depth = d;
    }

    std::vector<Task> tasks;
    for (size_t idx = 0; idx < depths.size(); ++idx) {
        int d = depths[idx].depth;
        int remaining = depths[idx].total_iters;
        int nodes_per_tree = (1 << (d + 1)) - 1;
        int chunk_size = std::max(1, (1 << 16) / nodes_per_tree);
        while (remaining > 0) {
            int cur = std::min(remaining, chunk_size);
            tasks.push_back({d, cur, static_cast<int>(idx)});
            remaining -= cur;
        }
    }

    // Process larger trees first to improve load balancing across threads
    std::sort(tasks.begin(), tasks.end(), [](const Task& a, const Task& b) {
        return a.depth > b.depth;
    });

    std::vector<std::atomic<int>> results(depths.size());
    for (auto& r : results) {
        r.store(0, std::memory_order_relaxed);
    }

    std::atomic<size_t> next_task{0};
    unsigned int num_threads = std::thread::hardware_concurrency();
    if (num_threads == 0) num_threads = 4;

    size_t max_short_nodes = 1ULL << (max_short_depth + 1);
    size_t thread_buf_bytes = max_short_nodes * sizeof(Node);

    std::vector<std::thread> workers;
    workers.reserve(num_threads);

    for (unsigned int t = 0; t < num_threads; ++t) {
        workers.emplace_back([&]() {
            Node* buf = static_cast<Node*>(std::malloc(thread_buf_bytes));
            while (true) {
                size_t task_id = next_task.fetch_add(1, std::memory_order_relaxed);
                if (task_id >= tasks.size()) break;

                const auto& task = tasks[task_id];
                int sum = 0;
                for (int i = 0; i < task.iters; ++i) {
                    Node* ptr = buf;
                    Node* root = make_tree(task.depth, ptr);
                    sum += check_tree(root);
                }
                results[task.depth_idx].fetch_add(sum, std::memory_order_relaxed);
            }
            std::free(buf);
        });
    }

    for (auto& w : workers) {
        w.join();
    }

    // 4. Output short-lived tree results
    for (size_t i = 0; i < depths.size(); ++i) {
        std::printf("%d\t trees of depth %d\t check: %d\n",
                    depths[i].total_iters,
                    depths[i].depth,
                    results[i].load(std::memory_order_relaxed));
    }

    // 5. Check and free long-lived tree
    int long_lived_check = check_tree(long_lived_tree);
    std::free(long_lived_buf);
    std::printf("long lived tree of depth %d\t check: %d\n", n, long_lived_check);

    return 0;
}
