#include <thread>
#include <atomic>
#include <algorithm>
#include <cstdint>
#include <cstdlib>

#if defined(__x86_64__) || defined(_M_X64)
#pragma GCC target("ssse3")
#include <tmmintrin.h>

alignas(16) static __m128i flip_masks[16];

static void init_masks() {
    for (int k = 0; k < 16; ++k) {
        alignas(16) uint8_t m[16];
        for (int i = 0; i <= k; ++i) {
            m[i] = static_cast<uint8_t>(k - i);
        }
        for (int i = k + 1; i < 16; ++i) {
            m[i] = static_cast<uint8_t>(i);
        }
        flip_masks[k] = _mm_load_si128(reinterpret_cast<const __m128i*>(m));
    }
}

static inline int count_flips_simd(const uint8_t* p) {
    if (p[0] == 0) return 0;
    __m128i q = _mm_load_si128(reinterpret_cast<const __m128i*>(p));
    uint32_t first = _mm_cvtsi128_si32(q) & 0xFF;
    int flips = 0;
    do {
        q = _mm_shuffle_epi8(q, flip_masks[first]);
        flips++;
        first = _mm_cvtsi128_si32(q) & 0xFF;
    } while (first != 0);
    return flips;
}
#else
static inline int count_flips_scalar(const uint8_t* p, int n) {
    if (p[0] == 0) return 0;
    uint8_t q[16];
    for (int i = 0; i < n; ++i) q[i] = p[i];
    int flips = 0;
    int first = q[0];
    do {
        for (int i = 0, j = first; i < j; ++i, --j) {
            uint8_t t = q[i];
            q[i] = q[j];
            q[j] = t;
        }
        flips++;
        first = q[0];
    } while (first != 0);
    return flips;
}
#endif

static void unrank(int n, int64_t idx, uint8_t p[16], int count[16], const int64_t fact[]) {
    for (int i = 0; i < 16; ++i) p[i] = static_cast<uint8_t>(i);
    for (int i = n - 1; i >= 1; --i) {
        int d = static_cast<int>(idx / fact[i]);
        idx %= fact[i];
        count[i] = (i + 1) - d;
        if (d > 0) {
            std::rotate(p, p + d, p + i + 1);
        }
    }
}

struct WorkerResult {
    int64_t checksum{0};
    int max_flips{0};
};

int main(int argc, char* argv[]) {
    int n = 12;
    if (argc > 1) {
        n = std::atoi(argv[1]);
    }

#if defined(__x86_64__) || defined(_M_X64)
    init_masks();
#endif

    int64_t fact[16];
    fact[0] = 1;
    for (int i = 1; i < 16; ++i) {
        fact[i] = fact[i - 1] * i;
    }

    int64_t total_permutations = fact[n];
    int64_t chunk_size = (n >= 4) ? fact[n - 3] : 1;
    int64_t total_chunks = total_permutations / chunk_size;

    unsigned int num_threads = std::thread::hardware_concurrency();
    if (num_threads == 0) num_threads = 4;
    num_threads = static_cast<unsigned int>(std::min<int64_t>(num_threads, total_chunks));
    if (num_threads == 0) num_threads = 1;

    std::atomic<int64_t> task_index{0};
    std::vector<WorkerResult> results(num_threads);
    std::vector<std::thread> threads;
    threads.reserve(num_threads);

    for (unsigned int tid = 0; tid < num_threads; ++tid) {
        threads.emplace_back([&, tid]() {
            alignas(16) uint8_t p[16];
            int count[16];
            int64_t local_checksum = 0;
            int local_max_flips = 0;

            while (true) {
                int64_t task_id = task_index.fetch_add(1, std::memory_order_relaxed);
                if (task_id >= total_chunks) break;

                int64_t idx_start = task_id * chunk_size;
                unrank(n, idx_start, p, count, fact);

                int sign = (idx_start & 1) ? -1 : 1;

                for (int64_t step = 0; step < chunk_size; ++step) {
                    int flips;
#if defined(__x86_64__) || defined(_M_X64)
                    flips = count_flips_simd(p);
#else
                    flips = count_flips_scalar(p, n);
#endif
                    local_checksum += sign * flips;
                    sign = -sign;
                    if (flips > local_max_flips) {
                        local_max_flips = flips;
                    }

                    if (step + 1 < chunk_size) {
                        int r = 1;
                        while (r < n) {
                            uint8_t p0 = p[0];
                            for (int i = 0; i < r; ++i) p[i] = p[i + 1];
                            p[r] = p0;
                            if (--count[r] > 0) break;
                            r++;
                        }
                        for (int i = 1; i < r; ++i) {
                            count[i] = i + 1;
                        }
                    }
                }
            }

            results[tid].checksum = local_checksum;
            results[tid].max_flips = local_max_flips;
        });
    }

    for (auto& t : threads) {
        t.join();
    }

    int64_t total_checksum = 0;
    int total_max_flips = 0;
    for (const auto& res : results) {
        total_checksum += res.checksum;
        total_max_flips = std::max(total_max_flips, res.max_flips);
    }

    std::cout << total_checksum << "\n";
    std::cout << "Pfannkuchen(" << n << ") = " << total_max_flips << "\n";

    return 0;
}
