static uint64_t count_kmer(const std::vector<uint8_t>& seq, const std::string& fragment) {
    size_t k = fragment.size();
    if (seq.size() < k) return 0;

    uint64_t target = 0;
    for (char c : fragment) {
        uint8_t v = 0;
        if (c == 'A' || c == 'a') v = 0;
        else if (c == 'C' || c == 'c') v = 1;
        else if (c == 'G' || c == 'g') v = 2;
        else if (c == 'T' || c == 't') v = 3;
        target = (target << 2) | v;
    }

    uint64_t mask = (k == 32) ? ~0ULL : ((1ULL << (2 * k)) - 1);

    uint64_t hash = 0;
    for (size_t i = 0; i < k - 1; ++i) {
        hash = (hash << 2) | seq[i];
    }

    uint64_t count = 0;
    for (size_t i = k - 1; i < seq.size(); ++i) {
        hash = ((hash << 2) | seq[i]) & mask;
        if (hash == target) {
            count++;
        }
    }
    return count;
}

static std::string get_frequencies(const std::vector<uint8_t>& seq, int k) {
    if (seq.size() < (size_t)k) {
        return "";
    }
    size_t num_kmers = 1ULL << (2 * k);
    std::vector<uint64_t> counts(num_kmers, 0);
    uint64_t mask = (1ULL << (2 * k)) - 1;

    uint64_t hash = 0;
    for (int i = 0; i < k - 1; ++i) {
        hash = (hash << 2) | seq[i];
    }
    for (size_t i = k - 1; i < seq.size(); ++i) {
        hash = ((hash << 2) | seq[i]) & mask;
        counts[hash]++;
    }

    uint64_t total = seq.size() - k + 1;

    struct Entry {
        uint64_t key;
        uint64_t count;
    };
    std::vector<Entry> entries;
    entries.reserve(num_kmers);
    for (size_t i = 0; i < num_kmers; ++i) {
        entries.push_back({i, counts[i]});
    }

    std::sort(entries.begin(), entries.end(), [](const Entry& a, const Entry& b) {
        if (a.count != b.count) return a.count > b.count;
        return a.key < b.key;
    });

    const char code_map[4] = {'A', 'C', 'G', 'T'};
    std::string result;
    char line_buf[64];
    for (const auto& e : entries) {
        std::string s(k, ' ');
        uint64_t temp = e.key;
        for (int i = k - 1; i >= 0; --i) {
            s[i] = code_map[temp & 3];
            temp >>= 2;
        }
        double pct = total > 0 ? (double)e.count * 100.0 / (double)total : 0.0;
        int len = snprintf(line_buf, sizeof(line_buf), "%s %.3f\n", s.c_str(), pct);
        result.append(line_buf, len);
    }
    return result;
}

int main(int argc, char* argv[]) {
