#include <algorithm>

struct BigInt {
    std::vector<uint64_t> a;
    bool neg = false;

    BigInt() {
        a.reserve(16000);
    }

    explicit BigInt(uint64_t v) {
        a.reserve(16000);
        if (v > 0) a.push_back(v);
    }

    bool empty() const { return a.empty(); }
    size_t size() const { return a.size(); }
    void clear() { a.clear(); neg = false; }

    void normalize() {
        while (!a.empty() && a.back() == 0) a.pop_back();
        if (a.empty()) neg = false;
    }
};

int cmp_abs(const BigInt& a, const BigInt& b) {
    if (a.size() != b.size()) return a.size() > b.size() ? 1 : -1;
    for (size_t i = a.size(); i-- > 0; ) {
        if (a.a[i] != b.a[i]) return a.a[i] > b.a[i] ? 1 : -1;
    }
    return 0;
}

void mul_small(BigInt& res, const BigInt& src, uint64_t m) {
    if (m == 0 || src.empty()) {
        res.clear();
        return;
    }
    static std::vector<uint64_t> mul_buf;
    if (mul_buf.capacity() < 16000) mul_buf.reserve(16000);
    mul_buf.resize(src.size());
    unsigned __int128 carry = 0;
    for (size_t i = 0; i < src.size(); ++i) {
        carry += (unsigned __int128)src.a[i] * m;
        mul_buf[i] = (uint64_t)carry;
        carry >>= 64;
    }
    if (carry) mul_buf.push_back((uint64_t)carry);
    res.a.swap(mul_buf);
    res.neg = src.neg;
}

void add_abs(BigInt& res, const BigInt& a, const BigInt& b) {
    static std::vector<uint64_t> add_buf;
    if (add_buf.capacity() < 16000) add_buf.reserve(16000);
    size_t na = a.size(), nb = b.size();
    size_t n = na > nb ? na : nb;
    add_buf.resize(n);
    unsigned __int128 carry = 0;
    size_t min_n = na < nb ? na : nb;
    for (size_t i = 0; i < min_n; ++i) {
        carry += (unsigned __int128)a.a[i] + b.a[i];
        add_buf[i] = (uint64_t)carry;
        carry >>= 64;
    }
    const BigInt& longer = na >= nb ? a : b;
    for (size_t i = min_n; i < n; ++i) {
        carry += longer.a[i];
        add_buf[i] = (uint64_t)carry;
        carry >>= 64;
    }
    if (carry) add_buf.push_back((uint64_t)carry);
    res.a.swap(add_buf);
}

void sub_abs(BigInt& res, const BigInt& a, const BigInt& b) {
    static std::vector<uint64_t> sub_buf;
    if (sub_buf.capacity() < 16000) sub_buf.reserve(16000);
    size_t na = a.size(), nb = b.size();
    sub_buf.resize(na);
    uint64_t borrow = 0;
    for (size_t i = 0; i < nb; ++i) {
        unsigned __int128 cur = a.a[i];
        unsigned __int128 sub_val = (unsigned __int128)b.a[i] + borrow;
        if (cur < sub_val) {
            cur += ((unsigned __int128)1 << 64);
            borrow = 1;
        } else {
            borrow = 0;
        }
        sub_buf[i] = (uint64_t)(cur - sub_val);
    }
    for (size_t i = nb; i < na; ++i) {
        uint64_t cur = a.a[i];
        if (borrow) {
            if (cur == 0) {
                sub_buf[i] = UINT64_MAX;
                borrow = 1;
            } else {
                sub_buf[i] = cur - 1;
                borrow = 0;
            }
        } else {
            sub_buf[i] = cur;
        }
    }
    res.a.swap(sub_buf);
    res.normalize();
}

void add(BigInt& res, const BigInt& a, const BigInt& b) {
    if (a.neg == b.neg) {
        add_abs(res, a, b);
        res.neg = a.neg;
    } else {
        int c = cmp_abs(a, b);
        if (c >= 0) {
            sub_abs(res, a, b);
            res.neg = a.neg;
        } else {
            sub_abs(res, b, a);
            res.neg = b.neg;
        }
    }
    res.normalize();
}

void sub(BigInt& res, const BigInt& a, const BigInt& b) {
    if (a.neg != b.neg) {
        add_abs(res, a, b);
        res.neg = a.neg;
    } else {
        int c = cmp_abs(a, b);
        if (c >= 0) {
            sub_abs(res, a, b);
            res.neg = a.neg;
        } else {
            sub_abs(res, b, a);
            res.neg = !a.neg;
        }
    }
    res.normalize();
}

int main(int argc, char* argv[]) {
    int n = 10000;
    if (argc > 1) {
        n = std::atoi(argv[1]);
    }

    BigInt q(1);
    BigInt r(0);
    BigInt t(1);

    BigInt tmp1, tmp2, num, rem;
    uint64_t k = 1;
    int digits_printed = 0;
    int line_digits = 0;

    while (digits_printed < n) {
        mul_small(tmp1, q, 3);
        add(num, tmp1, r);

        uint32_t d = 0;
        if (num.size() == t.size()) {
            d = num.a.back() / t.a.back();
        } else if (num.size() == t.size() + 1) {
            unsigned __int128 top = ((unsigned __int128)num.a.back() << 64) | num.a[t.size() - 1];
            d = (uint32_t)(top / t.a.back());
        } else if (num.size() < t.size()) {
            d = 0;
        } else {
            d = 10;
        }
        if (d > 9) d = 9;

        mul_small(tmp1, t, d);
        sub(rem, num, tmp1);

        while (rem.neg && d > 0) {
            add(rem, rem, t);
            --d;
        }
        while (!rem.neg && cmp_abs(rem, t) >= 0) {
            sub(rem, rem, t);
            ++d;
        }

        if (d <= 9) {
            add(tmp1, rem, q);
            if (cmp_abs(tmp1, t) < 0) {
                putchar('0' + d);
                ++digits_printed;
                ++line_digits;
                if (line_digits == 10) {
                    printf("\t:%d\n", digits_printed);
                    line_digits = 0;
                }

                mul_small(tmp1, t, d);
                sub(tmp2, r, tmp1);
                mul_small(r, tmp2, 10);
                mul_small(q, q, 10);
                continue;
            }
        }

        uint64_t p = 2 * k + 1;
        mul_small(tmp1, q, 2 * p);
        mul_small(r, r, p);
        add(r, r, tmp1);
        mul_small(t, t, p);
        mul_small(q, q, k);
        ++k;
    }

    if (line_digits > 0) {
        for (int i = line_digits; i < 10; ++i) {
            putchar(' ');
        }
        printf("\t:%d\n", digits_printed);
    }

    return 0;
}
