// 1: [cgt]gggtaaa|tttaccc[acg]
// 2: a[act]ggtaaa|tttacc[agt]t
// 3: ag[act]gtaaa|tttac[agt]ct
// 4: agg[act]taaa|ttta[agt]cct
// 5: aggg[acg]aaa|ttt[cgt]ccct
// 6: agggt[cgt]aa|tt[acg]accct
// 7: agggta[cgt]a|t[acg]taccct
// 8: agggtaa[cgt]|[acg]ttaccct

struct PatternDef {
    const char* name;
    // Each pattern has length 8. We can check whether seq[i..i+7] matches branch A or branch B.
};

static const PatternDef PATTERNS[9] = {
    {"agggtaaa|tttaccct"},
    {"[cgt]gggtaaa|tttaccc[acg]"},
    {"a[act]ggtaaa|tttacc[agt]t"},
    {"ag[act]gtaaa|tttac[agt]ct"},
    {"agg[act]taaa|ttta[agt]cct"},
    {"aggg[acg]aaa|ttt[cgt]ccct"},
    {"agggt[cgt]aa|tt[acg]accct"},
    {"agggta[cgt]a|t[acg]taccct"},
    {"agggtaa[cgt]|[acg]ttaccct"}
};

static inline bool match_at(int p_idx, const char* s) {
    switch (p_idx) {
        case 0:
            return (memcmp(s, "agggtaaa", 8) == 0) || (memcmp(s, "tttaccct", 8) == 0);
        case 1:
            return ((s[0] == 'c' || s[0] == 'g' || s[0] == 't') && memcmp(s + 1, "gggtaaa", 7) == 0) ||
                   (memcmp(s, "tttaccc", 7) == 0 && (s[7] == 'a' || s[7] == 'c' || s[7] == 'g'));
        case 2:
            return (s[0] == 'a' && (s[1] == 'a' || s[1] == 'c' || s[1] == 't') && memcmp(s + 2, "ggtaaa", 6) == 0) ||
                   (memcmp(s, "tttacc", 6) == 0 && (s[6] == 'a' || s[6] == 'g' || s[6] == 't') && s[7] == 't');
        case 3:
            return (s[0] == 'a' && s[1] == 'g' && (s[2] == 'a' || s[2] == 'c' || s[2] == 't') && memcmp(s + 3, "gtaaa", 5) == 0) ||
                   (memcmp(s, "tttac", 5) == 0 && (s[5] == 'a' || s[5] == 'g' || s[5] == 't') && s[6] == 'c' && s[7] == 't');
        case 4:
            return (s[0] == 'a' && s[1] == 'g' && s[2] == 'g' && (s[3] == 'a' || s[3] == 'c' || s[3] == 't') && memcmp(s + 4, "taaa", 4) == 0) ||
                   (memcmp(s, "ttta", 4) == 0 && (s[4] == 'a' || s[4] == 'g' || s[4] == 't') && memcmp(s + 5, "cct", 3) == 0);
        case 5:
            return (memcmp(s, "aggg", 4) == 0 && (s[4] == 'a' || s[4] == 'c' || s[4] == 'g') && memcmp(s + 5, "aaa", 3) == 0) ||
                   (memcmp(s, "ttt", 3) == 0 && (s[3] == 'c' || s[3] == 'g' || s[3] == 't') && memcmp(s + 4, "ccct", 4) == 0);
        case 6:
            return (memcmp(s, "agggt", 5) == 0 && (s[5] == 'c' || s[5] == 'g' || s[5] == 't') && s[6] == 'a' && s[7] == 'a') ||
                   (s[0] == 't' && s[1] == 't' && (s[2] == 'a' || s[2] == 'c' || s[2] == 'g') && memcmp(s + 3, "accct", 5) == 0);
        case 7:
            return (memcmp(s, "agggta", 6) == 0 && (s[6] == 'c' || s[6] == 'g' || s[6] == 't') && s[7] == 'a') ||
                   (s[0] == 't' && (s[1] == 'a' || s[1] == 'c' || s[1] == 'g') && memcmp(s + 2, "taccct", 6) == 0);
        case 8:
            return (memcmp(s, "agggtaa", 7) == 0 && (s[7] == 'c' || s[7] == 'g' || s[7] == 't')) ||
                   ((s[0] == 'a' || s[0] == 'c' || s[0] == 'g') && memcmp(s + 1, "ttaccct", 7) == 0);
        default:
            return false;
    }
}

static int count_matches(int p_idx, const std::string& seq) {
    int count = 0;
    size_t n = seq.size();
    if (n < 8) return 0;
    const char* data = seq.data();
    size_t limit = n - 8;
    for (size_t i = 0; i <= limit; ) {
        if (match_at(p_idx, data + i)) {
            count++;
            i += 8;
        } else {
            i++;
        }
    }
    return count;
}

// Substitutions:
// 1. tHa[Nt]            -> <4>
// 2. aND|caN|Ha[DS]|WaS -> <3>
// 3. a[NSt]|BY          -> <2>
// 4. <[^>]*>            -> |
// 5. \|[^|][^|]*\|      -> -

static std::string sub1(const std::string& in) {
    std::string out;
    out.reserve(in.size());
    size_t n = in.size();
    const char* s = in.data();
    for (size_t i = 0; i < n; ) {
        if (i + 4 <= n && s[i] == 't' && s[i + 1] == 'H' && s[i + 2] == 'a' && (s[i + 3] == 'N' || s[i + 3] == 't')) {
            out.append("<4>");
            i += 4;
        } else {
            out.push_back(s[i++]);
        }
    }
    return out;
}

static std::string sub2(const std::string& in) {
    std::string out;
    out.reserve(in.size());
    size_t n = in.size();
    const char* s = in.data();
    for (size_t i = 0; i < n; ) {
        if (i + 3 <= n) {
            if ((s[i] == 'a' && s[i + 1] == 'N' && s[i + 2] == 'D') ||
                (s[i] == 'c' && s[i + 1] == 'a' && s[i + 2] == 'N') ||
                (s[i] == 'H' && s[i + 1] == 'a' && (s[i + 2] == 'D' || s[i + 2] == 'S')) ||
                (s[i] == 'W' && s[i + 1] == 'a' && s[i + 2] == 'S')) {
                out.append("<3>");
                i += 3;
                continue;
            }
        }
        out.push_back(s[i++]);
    }
    return out;
}

static std::string sub3(const std::string& in) {
    std::string out;
    out.reserve(in.size());
    size_t n = in.size();
    const char* s = in.data();
    for (size_t i = 0; i < n; ) {
        if (i + 2 <= n) {
            if ((s[i] == 'a' && (s[i + 1] == 'N' || s[i + 1] == 'S' || s[i + 1] == 't')) ||
                (s[i] == 'B' && s[i + 1] == 'Y')) {
                out.append("<2>");
                i += 2;
                continue;
            }
        }
        out.push_back(s[i++]);
    }
    return out;
}

static std::string sub4(const std::string& in) {
    std::string out;
    out.reserve(in.size());
    size_t n = in.size();
    const char* s = in.data();
    for (size_t i = 0; i < n; ) {
        if (s[i] == '<') {
            size_t j = i + 1;
            while (j < n && s[j] != '>') {
                j++;
            }
            if (j < n && s[j] == '>') {
                out.push_back('|');
                i = j + 1;
                continue;
            }
        }
        out.push_back(s[i++]);
    }
    return out;
}

static std::string sub5(const std::string& in) {
    std::string out;
    out.reserve(in.size());
    size_t n = in.size();
    const char* s = in.data();
    for (size_t i = 0; i < n; ) {
        if (s[i] == '|') {
            size_t j = i + 1;
            while (j < n && s[j] != '|') {
                j++;
            }
            // Must have at least one non-| char: j > i + 1
            if (j < n && s[j] == '|' && j > i + 1) {
                out.push_back('-');
                i = j + 1;
                continue;
            }
        }
        out.push_back(s[i++]);
    }
    return out;
}

int main(int argc, char** argv) {
    // Read all of stdin
    std::string input;
    constexpr size_t BUF_SIZE = 65536;
    char buffer[BUF_SIZE];
    while (true) {
        size_t bytes_read = fread(buffer, 1, BUF_SIZE, stdin);
        if (bytes_read == 0) break;
        input.append(buffer, bytes_read);
    }
    size_t orig_len = input.size();

    // Strip FASTA headers (>.*\n) and remaining newlines (\n)
    std::string stripped;
    stripped.reserve(orig_len);
    const char* p = input.data();
    const char* end = p + orig_len;

    while (p < end) {
        if (*p == '>') {
            while (p < end && *p != '\n') {
                p++;
            }
            if (p < end && *p == '\n') {
                p++;
            }
        } else if (*p == '\n') {
            p++;
        } else {
            stripped.push_back(*p++);
        }
    }
    size_t stripped_len = stripped.size();

    // Launch pattern counts in parallel
    std::future<int> counts[9];
    for (int i = 0; i < 9; ++i) {
        counts[i] = std::async(std::launch::async, count_matches, i, std::cref(stripped));
    }

    // Launch substitutions
    auto sub_fut = std::async(std::launch::async, [&stripped]() {
        std::string s = sub1(stripped);
        s = sub2(s);
        s = sub3(s);
        s = sub4(s);
        s = sub5(s);
        return s.size();
    });

    for (int i = 0; i < 9; ++i) {
        int count = counts[i].get();
        std::cout << PATTERNS[i].name << ' ' << count << '\n';
    }

    size_t final_len = sub_fut.get();

    std::cout << '\n'
              << orig_len << '\n'
              << stripped_len << '\n'
              << final_len << '\n';

    return 0;
}
