static unsigned char comp[256];

static void init_comp() {
    for (int i = 0; i < 256; ++i) {
        comp[i] = 0;
    }
    auto set_pair = [](char c1, char c2) {
        comp[(unsigned char)c1] = (unsigned char)c2;
        comp[(unsigned char)std::tolower(c1)] = (unsigned char)c2;
        comp[(unsigned char)c2] = (unsigned char)c1;
        comp[(unsigned char)std::tolower(c2)] = (unsigned char)c1;
    };

    set_pair('A', 'T');
    set_pair('C', 'G');
    set_pair('M', 'K');
    set_pair('R', 'Y');
    set_pair('V', 'B');
    set_pair('H', 'D');

    comp['U'] = 'A'; comp['u'] = 'A';
    comp['W'] = 'W'; comp['w'] = 'W';
    comp['S'] = 'S'; comp['s'] = 'S';
    comp['N'] = 'N'; comp['n'] = 'N';
}

static void write_all(int fd, const char* data, size_t size) {
    size_t written = 0;
    while (written < size) {
        ssize_t n = write(fd, data + written, size - written);
        if (n < 0) {
            if (errno == EINTR) continue;
            break;
        }
        written += n;
    }
}

int main(int argc, char* argv[]) {
    int N = 0;
    if (argc > 1) {
        N = std::atoi(argv[1]);
    }
    (void)N;

    init_comp();

    // Read all of stdin into a contiguous memory buffer
    size_t total = 0;
    std::vector<char> input(1 << 20);
    while (true) {
        if (total == input.size()) {
            input.resize(input.size() * 2);
        }
        ssize_t n = read(0, input.data() + total, input.size() - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            break;
        }
        if (n == 0) break;
        total += n;
    }
    input.resize(total);

    constexpr size_t OUT_CAP = 1024 * 1024;
    std::vector<char> out_buf(OUT_CAP);
    size_t out_len = 0;

    auto flush = [&]() {
        if (out_len > 0) {
            write_all(1, out_buf.data(), out_len);
            out_len = 0;
        }
    };

    size_t cur = 0;
    while (cur < total) {
        // Locate start of FASTA header
        while (cur < total && input[cur] != '>') {
            cur++;
        }
        if (cur >= total) break;

        size_t h_start = cur;
        while (cur < total && input[cur] != '\n') {
            cur++;
        }
        if (cur < total && input[cur] == '\n') {
            cur++;
        }
        size_t h_end = cur;
        size_t seq_start = h_end;

        // Locate next header start
        while (cur < total) {
            if (input[cur] == '>' && (cur == 0 || input[cur - 1] == '\n')) {
                break;
            }
            cur++;
        }
        size_t seq_end = cur;

        // Write header unchanged
        flush();
        write_all(1, input.data() + h_start, h_end - h_start);

        // Reverse-complement the sequence and output in lines of 60 characters
        int col = 0;
        for (const char* p = input.data() + seq_end - 1; p >= input.data() + seq_start; --p) {
            unsigned char rc = comp[(unsigned char)*p];
            if (rc) {
                out_buf[out_len++] = (char)rc;
                if (++col == 60) {
                    out_buf[out_len++] = '\n';
                    col = 0;
                }
                if (out_len >= OUT_CAP - 64) {
                    flush();
                }
            }
        }
        if (col != 0) {
            out_buf[out_len++] = '\n';
        }
        flush();
    }

    return 0;
}
