class Barrier {
    std::mutex mtx;
    std::condition_variable cv;
    int count;
    int total;
    int generation;

public:
    explicit Barrier(int n) : count(n), total(n), generation(0) {}

    void wait() {
        std::unique_lock<std::mutex> lock(mtx);
        int gen = generation;
        if (--count == 0) {
            generation++;
            count = total;
            cv.notify_all();
        } else {
            cv.wait(lock, [this, gen] { return gen != generation; });
        }
    }
};

int main(int argc, char* argv[]) {
    if (argc < 2) return 1;
    int N = std::atoi(argv[1]);
    if (N <= 0) return 0;

    std::vector<double> u(N, 1.0);
    std::vector<double> v(N, 0.0);
    std::vector<double> tmp(N, 0.0);

    unsigned int num_threads = std::thread::hardware_concurrency();
    if (num_threads == 0) num_threads = 4;
    if (static_cast<int>(num_threads) > N) num_threads = N;

    Barrier barrier(num_threads);

    auto worker = [&](int tid) {
        int i_begin = tid * N / num_threads;
        int i_end = (tid + 1) * N / num_threads;

        for (int iter = 0; iter < 10; ++iter) {
            // Step 1: tmp = A * u
            for (int i = i_begin; i < i_end; ++i) {
                double sum = 0.0;
                #pragma GCC ivdep
                for (int j = 0; j < N; ++j) {
                    sum += u[j] / ((i + j) * (i + j + 1) / 2 + i + 1);
                }
                tmp[i] = sum;
            }
            barrier.wait();

            // Step 2: v = At * tmp
            for (int i = i_begin; i < i_end; ++i) {
                double sum = 0.0;
                #pragma GCC ivdep
                for (int j = 0; j < N; ++j) {
                    sum += tmp[j] / ((i + j) * (i + j + 1) / 2 + j + 1);
                }
                v[i] = sum;
            }
            barrier.wait();

            // Step 3: tmp = A * v
            for (int i = i_begin; i < i_end; ++i) {
                double sum = 0.0;
                #pragma GCC ivdep
                for (int j = 0; j < N; ++j) {
                    sum += v[j] / ((i + j) * (i + j + 1) / 2 + i + 1);
                }
                tmp[i] = sum;
            }
            barrier.wait();

            // Step 4: u = At * tmp
            for (int i = i_begin; i < i_end; ++i) {
                double sum = 0.0;
                #pragma GCC ivdep
                for (int j = 0; j < N; ++j) {
                    sum += tmp[j] / ((i + j) * (i + j + 1) / 2 + j + 1);
                }
                u[i] = sum;
            }
            barrier.wait();
        }
    };

    std::vector<std::thread> threads;
    threads.reserve(num_threads - 1);
    for (unsigned int t = 1; t < num_threads; ++t) {
        threads.emplace_back(worker, t);
    }
    worker(0);
    for (auto& t : threads) {
        t.join();
    }

    double vBv = 0.0;
